processPrePosts.script:
if (tw.local.results[0].rows.listLength == 0) {

	 tw.local.message = "Request number does not exist or is in another running request";

	 tw.local.isFound = false;
	

}

TWComponent.script:
tw.local.errorMSG = "This CIF Number Not related to Parent Request Number";
tw.local.isCIFMatch = false;


tw.local.parentODCRequest.CustomerInfo = tw.local.customerInfo;
tw.local.parentODCRequest.cif = tw.local.parentODCRequest.CustomerInfo.cif;
tw.local.parentODCRequest.customerName =tw.local.parentODCRequest.CustomerInfo.customerName;

tw.local.parentODCRequest.requestNature.value = tw.local.requestNature;
tw.local.parentODCRequest.requestType.value = tw.local.requestType;

tw.local.parentODCRequest.ImporterName = null;
tw.local.parentODCRequest.requestDate = null;

if ( tw.local.requestType == tw.epv.RequestType.Recreate ){
	var documentAmount = tw.local.parentODCRequest.FinancialDetailsBR.documentAmount || 0;
	var extraCharges =  tw.local.parentODCRequest.FinancialDetailsFO.extraCharges || 0;
	var discount = tw.local.parentODCRequest.FinancialDetailsFO.discount || 0;
	var amountAdvanced = tw.local.parentODCRequest.FinancialDetailsBR.amountAdvanced || 0;
	var calcAmnt = documentAmount + extraCharges - discount - amountAdvanced;
	tw.local.parentODCRequest.FinancialDetailsFO.collectableAmount = calcAmnt;
}

processPrePosts.script:
tw.local.isFound = true;

if (tw.local.results[0].rows.listLength == 0) {
	tw.local.message = "Request number does not exist or is in another running request ";
	tw.local.isFound = false;
}

if (!!tw.local.results[1]) {
	if (tw.local.results[1].rows.listLength > 0) {
		tw.local.message = "Request number is in another running request ";
		tw.local.isFound = false;
	}
}

tw.local.parentODCRequest.collectionDone = false;

if (!!tw.local.results[2]) {
	if (tw.local.results[2].rows[0].data[0] > 0) {
		if (tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Recreate) {
			tw.local.message = "A collection request exists. There must be no collection request to proceed.";
			tw.local.isFound = false;
		}
		tw.local.parentODCRequest.FinancialDetailsFO = new tw.object.FinancialDetailsFO();
		tw.local.parentODCRequest.FinancialDetailsFO.totalCollectedAmount = tw.local.results[2].rows[0].data[0];
		tw.local.parentODCRequest.collectionDone = true;
	}
}

if (!!tw.local.results[3]) {
	if (tw.local.results[3].rows.listLength > 0) {
		tw.local.message = "Request can not be started.Closure request is completed for this request number.";
		tw.local.isFound = false;
	}
}

if (tw.local.parentODCRequest.requestType.value != tw.epv.RequestType.Create +"") {
	if (!!tw.local.results[4]) {
		if (tw.local.results[4].rows.listLength > 0) {
			if (tw.local.results[4].rows[0].data[0] == tw.epv.RequestState.Reversed) {
				tw.local.message = "Request can not be started.Reversal request is completed for this request number.";
				tw.local.isFound = false;
			}
		}
	}

	if (tw.local.parentODCRequest.requestType.value != tw.epv.RequestType.Reversal) {
		if (!!tw.local.results[5]) {
			if (tw.local.results[5].rows.listLength > 0) {
				tw.local.message = "Request can not be started as the Outstanding Amount = 0";
				tw.local.isFound = false;
			}
		}
	}
}


// tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Collection || tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Closure || tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Reversal || tw.local.parentODCRequest.requestType.value == "" + tw.epv.RequestType.Recreate

TWComponent.script:
if (tw.local.results[0].rows.listLength == 0) {
      if(tw.local.parentODCRequest.requestType.value == "amend" || tw.local.parentODCRequest.requestType.value == "closure" || tw.local.parentODCRequest.requestType.value == "collection"){
	 tw.local.message = "Request number does not exist or is in another running request or Outstanding amount is not > 0 ";
	}
	else
	 tw.local.message = "Request number does not exist or is in another running request";
	tw.local.isFound = false;
}

else{

      tw.local.isFound = true;
      
      if(tw.local.parentODCRequest.requestType.value == "recreate"){
      
      //There must be no collection done on ODC

         for(var i =0 ; i <tw.local.results[0].rows.listLength; i++){

             if(tw.local.results[0].rows[i].data[3] == "ODC Collection"){
                  tw.local.message = "There must be no collection done on ODC";
                  tw.local.isFound = false;
                  break;
             }
          }
          if(tw.local.isFound == true ){
          //get the latsest instance
           tw.local.results[0].rows[0] = tw.local.results[0].rows[tw.local.results[0].rows.listLength-1];

          }
      }
	
}

