processPrePosts.script:
tw.local.requestType = tw.local.parentODCRequest.requestType.value;
tw.local.requestNature = ""+ tw.epv.RequestNature.UpdateRequest;
tw.local.parentODCRequest.parentRequestNo = tw.local.requestNumber;
tw.local.appInfo = tw.local.parentODCRequest.appInfo;
