tw.local.isCIFMatch = true;
tw.local.errorMSG ="";

TWComponent.script:
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var j = 0;
var i = 0;
function paramInit(value) {
	tw.local.sqlStatements[j].parameters[i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[j].parameters[i].value = value;
	i++;
}

var final = "" + tw.epv.RequestState.Final;
var closed = "" + tw.epv.RequestState.Closed;
var reversed = "" + tw.epv.RequestState.Reversed;
var collected = "" + tw.epv.RequestState.Collection;
var amend = "" + tw.epv.RequestType.Amendment;
var recreate = "" + tw.epv.RequestType.Recreate;
var collection = "" + tw.epv.RequestType.Collection;
var closure = "" + tw.epv.RequestType.Closure;
var reversal = "" + tw.epv.RequestType.Reversal;
var create = "" + tw.epv.RequestType.Create;
var completed = "" + tw.epv.Status.completed;
var approved = "" + tw.epv.Status.Approved;
var create = "" + tw.epv.RequestType.Create;
var terminated = "" + tw.epv.Status.terminated;
var cancelled = "" + tw.epv.Status.Canceled;
//check parent request is completed
tw.local.sqlStatements[j] = {};
tw.local.sqlStatements[j].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE REQUESTNO = ? AND REQUESTSTATE = '" + final + "' AND REQUESTSTATUS = '" + completed + "';";

tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

//check there's no running request
j++;
i = 0;
tw.local.sqlStatements[j] = {};
tw.local.sqlStatements[j].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND (REQUESTTYPE = '" + amend + "' OR REQUESTTYPE = '" + recreate + "' OR REQUESTTYPE = '" + collection + "' OR REQUESTTYPE = '" + reversal + "'OR REQUESTTYPE = '" + closure + "') AND (REQUESTSTATUS != '" + completed + "' AND REQUESTSTATUS != '" + terminated + "' AND REQUESTSTATUS != '" + cancelled + "'  AND REQUESTSTATUS != '" + approved + "');";

tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

// check if there's a collection request
j++;
i = 0;
tw.local.sqlStatements[j] = {};
tw.local.sqlStatements[j].sql = "SELECT SUM(liqAmount) FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND REQUESTSTATE = '" + collected + "' AND REQUESTSTATUS = '" + completed + "';";

tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

//check there's no completed closure request
j++;
i = 0;
tw.local.sqlStatements[j] = {};
tw.local.sqlStatements[j].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND REQUESTSTATE = '" + closed + "' AND REQUESTSTATUS = '" + completed + "';";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

if (tw.local.parentODCRequest.requestType.value != tw.epv.RequestType.Create + "") {
	//check no reversal is requested in case of requesting another amend,collecion,closure
	j++;
	i = 0;
	tw.local.sqlStatements[j] = {};
	tw.local.sqlStatements[j].sql = "SELECT REQUESTSTATE FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND REQUESTSTATUS != '" + terminated + "' AND REQUESTSTATUS != '" + cancelled + "'  );";

	tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
	paramInit(tw.local.parentODCRequest.parentRequestNo);

	if (tw.local.parentODCRequest.requestType.value != reversal) {
		//check outstanding amount >0
		j++;
		i = 0;
		tw.local.sqlStatements[j] = {};
		tw.local.sqlStatements[j].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND (REQUESTTYPE = '" + amend + "' OR REQUESTTYPE = '" + recreate + "' OR REQUESTTYPE = '" + create + "' OR REQUESTTYPE = '" + collection + "') AND (REQUESTSTATE = '" + final + "' OR REQUESTSTATE = '" + collected + "') AND REQUESTSTATUS='" + completed + "' AND OUTSTANDINGAMOUNT =0);";
		tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
		paramInit(tw.local.parentODCRequest.parentRequestNo);
	}
}


// tw.local.parentODCRequest.requestType.value == amend || tw.local.parentODCRequest.requestType.value == collection || tw.local.parentODCRequest.requestType.value == closure || tw.local.parentODCRequest.requestType.value == reversal

