TWComponent.script:
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var j = 0;
var i = 0;
function paramInit (value) {
	tw.local.sqlStatements[j].parameters[i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[j].parameters[i].value = value;
	i++;
}

//------------------------------------- Get invoice --------------------------------------------
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT  INVOICENO, INVOICEDATE FROM "+ tw.env.LKP_DB_Schema +".ODC_INVOICE WHERE REQUESRID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);

//------------------------------------- Get bills --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT BILLOFLADINGREF, BILLOFLADINGDATE FROM "+ tw.env.LKP_DB_Schema +".ODC_BILLS WHERE REQUESRID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);


//------------------------------------- Get multi tenor --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT INSTALLMENTDATE, INSTALLMENTAMOUNT, INSTALLMENTBASEDATE, INSTALLMENTTENORDAYS, LIQUIDATION_AMOUNT FROM "+ tw.env.LKP_DB_Schema +".ODC_MULTITENORDATES WHERE REQUESRID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);



//------------------------------------- Get delivery terms --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT DESCRIPTION , DELIVERYTERMVALUE  FROM "+ tw.env.LKP_DB_Schema +".ODC_DELIVERYTERMS delv Inner join  "+ tw.env.LKP_DB_Schema +".ODC_REMITTANCE_LETTER_INSTRUCTIONS rem on rem.id = delv.DELIVERYTERMVALUE   WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);
   
//------------------------------------- Get delivery terms extra --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT DELIVERYTERMEXTRA   FROM "+ tw.env.LKP_DB_Schema +".ODC_DELIVERYTERMSEXTRA  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);
  
//------------------------------------- Get payment instructions--------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT DESCRIPTION , PAYMENTINSTRUCTIONSVALUE  FROM "+ tw.env.LKP_DB_Schema +".ODC_PAYMENTINSTRUCTIONS pmnt Inner join  "+ tw.env.LKP_DB_Schema +".ODC_REMITTANCE_LETTER_INSTRUCTIONS rem on rem.id = pmnt.PAYMENTINSTRUCTIONSVALUE   WHERE REQUESTID = ? ;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);
  
 //------------------------------------- Get payment instructions extra--------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT PAYMENTINSTRUCTIONSEXTRA FROM "+ tw.env.LKP_DB_Schema +".ODC_PAYMENTINSTRUCTIONSEXTRA  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);
 
 //------------------------------------- instructions--------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT DESCRIPTION , INSTRUCTIONSVALUE  FROM "+ tw.env.LKP_DB_Schema +".ODC_INSTRUCTIONS ins Inner join  "+ tw.env.LKP_DB_Schema +".ODC_REMITTANCE_LETTER_INSTRUCTIONS rem on rem.id = ins.INSTRUCTIONSVALUE   WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);
  
 //------------------------------------- instructions extra--------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT INSTRUCTIONSEXTRA  FROM "+ tw.env.LKP_DB_Schema +".ODC_INSTRUCTIONSEXTRA  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);
   
 //------------------------------------- special instructions --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT DESCRIPTION , SPECIALINSTRUCTIONSVALUE  FROM "+ tw.env.LKP_DB_Schema +".ODC_SPECIALINSTRUCTIONS sins Inner join  "+ tw.env.LKP_DB_Schema +".ODC_REMITTANCE_LETTER_INSTRUCTIONS rem on rem.id = sins.SPECIALINSTRUCTIONSVALUE   WHERE REQUESTID = ? ;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);
   
   
  //------------------------------------- special instructions extra --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT SPECIALINSTRUCTIONSEXTRA FROM "+ tw.env.LKP_DB_Schema +".ODC_SPECIALINSTRUCTIONSEXTRA  WHERE REQUESTID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0])
   paramInit(tw.local.results[0].rows[0].data[0]);


////------------------------------------- Get Transactions --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql= "SELECT f.ACCOUNTNO, f.REFERENCENO, f.POSTINGDATE, f.VALUEDATE, f.TRANSACTIONAMOUNT, f.AMOUNTLINKEDINBPM, s.AMOUNTINCURRENTREQ, s.AMOUNTINREQCURRENCY, f.ID " +
					"FROM "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION f JOIN "+tw.env.LKP_DB_Schema+".ODC_SELECTEDTRANSACTIONS s ON f.ID = s.TRANSACTIONID WHERE s.REQUESTID = ? "+
					"AND s.ID IN (SELECT MAX(s2.ID) FROM "+tw.env.LKP_DB_Schema+".ODC_SELECTEDTRANSACTIONS s2 WHERE s2.REQUESTID = ? AND (s2.isDeleted <> 'Yes' OR s2.isDeleted IS NULL) GROUP BY s2.TRANSACTIONID);";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
if(!!tw.local.results[0].rows[0]){
   paramInit(tw.local.results[0].rows[0].data[0]);
    paramInit(tw.local.results[0].rows[0].data[0]);
  }

