ns16:extensionElements.ns2:preAssignmentScript:
tw.local.requestType = tw.local.parentODCRequest.requestType.value;
tw.local.requestNature = ""+ tw.epv.RequestNature.UpdateRequest;
tw.local.appInfo = tw.local.parentODCRequest.appInfo;
tw.local.customerInfo = tw.local.parentODCRequest.CustomerInfo;

ns16:scriptTask.ns16:script:
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var j = 0;
var i = 0;
function paramInit (value) {
	tw.local.sqlStatements[j].parameters[i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[j].parameters[i].value = value;
	i++;
}
//------------------------------------- Get ODC -------------------------------------------- 
var final = "" +tw.epv.RequestState.Final;
var closed = "" + tw.epv.RequestState.Closed;
var reversed = "" + tw.epv.RequestState.Reversed;
var collected = ""+ tw.epv.RequestState.Collection;

tw.local.sqlStatements[j] = new tw.object.SQLStatement();

if(tw.local.parentODCRequest.requestType.value == "amend" || tw.local.parentODCRequest.requestType.value == "closure" || tw.local.parentODCRequest.requestType.value == "collection"){
 tw.local.sqlStatements[j].sql="SELECT * FROM ARCHUSR.ODC_REQUESTINFO WHERE REQUESTSTATE = '"+final+"' OR REQUESTSTATE = '"+collected+"' OR REQUESTSTATE = '"+closed+"' OR REQUESTSTATE = '"+reversed+"'  AND UPPER(REQUESTSTATUS) = UPPER('Completed') AND ID = (SELECT max(ID) FROM ARCHUSR.ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND UPPER(REQUESTSTATUS) != UPPER('Terminated') AND UPPER(REQUESTSTATUS) != UPPER('Canceled') )  AND OUTSTANDINGAMOUNT > 0; ";

}
else if (tw.local.parentODCRequest.requestType.value == "recreate"){
 tw.local.sqlStatements[j].sql="SELECT * FROM ARCHUSR.ODC_REQUESTINFO WHERE REQUESTSTATE = '"+final+"' AND UPPER(REQUESTSTATUS) = UPPER('Completed') AND   PARENTREQUESTNO = ? AND UPPER(REQUESTSTATUS) !=  UPPER('Terminated') AND UPPER(REQUESTSTATUS) != UPPER('Canceled') ORDER BY ID ASC";

}

else{
