ns16:scriptTask.ns16:script:
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var j = 0;
var i = 0;
function paramInit(value) {
	tw.local.sqlStatements[j].parameters[i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[j].parameters[i].value = value;
	i++;
}

var final = "" + tw.epv.RequestState.Final;
var closed = "" + tw.epv.RequestState.Closed;
var reversed = "" + tw.epv.RequestState.Reversed;
var collected = "" + tw.epv.RequestState.Collection;
var amend = "" + tw.epv.RequestType.Amendment;
var recreate = "" + tw.epv.RequestType.Recreate;
var collection = "" + tw.epv.RequestType.Collection;
var closure = "" + tw.epv.RequestType.Closure;
var reversal = "" + tw.epv.RequestType.Reversal;
var create = "" + tw.epv.RequestType.Create;
var completed = "" + tw.epv.Status.completed;
var approved = "" + tw.epv.Status.Approved;
var create = "" + tw.epv.RequestType.Create;
var terminated = "" + tw.epv.Status.terminated;
var cancelled = "" + tw.epv.Status.Canceled;
//check parent request is completed
tw.local.sqlStatements[j] = {};
tw.local.sqlStatements[j].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE REQUESTNO = ? AND REQUESTSTATE = '" + final + "' AND REQUESTSTATUS = '" + completed + "';";

tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

//check there's no running request
j++;
i = 0;
tw.local.sqlStatements[j] = {};
tw.local.sqlStatements[j].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND (REQUESTTYPE = '" + amend + "' OR REQUESTTYPE = '" + recreate + "' OR REQUESTTYPE = '" + collection + "' OR REQUESTTYPE = '" + reversal + "'OR REQUESTTYPE = '" + closure + "') AND (REQUESTSTATUS != '" + completed + "' AND REQUESTSTATUS != '" + terminated + "' AND REQUESTSTATUS != '" + cancelled + "'  AND REQUESTSTATUS != '" + approved + "');";

tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

// check if there's a collection request
j++;
i = 0;
tw.local.sqlStatements[j] = {};
tw.local.sqlStatements[j].sql = "SELECT SUM(liqAmount) FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND REQUESTSTATE = '" + collected + "' AND REQUESTSTATUS = '" + completed + "';";

tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

//check there's no completed closure request
j++;
i = 0;
tw.local.sqlStatements[j] = {};
tw.local.sqlStatements[j].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND REQUESTSTATE = '" + closed + "' AND REQUESTSTATUS = '" + completed + "';";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

if (tw.local.parentODCRequest.requestType.value != tw.epv.RequestType.Create + "") {
	//check no reversal is requested in case of requesting another amend,collecion,closure
	j++;
	i = 0;
	tw.local.sqlStatements[j] = {};
	tw.local.sqlStatements[j].sql = "SELECT REQUESTSTATE FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND REQUESTSTATUS != '" + terminated + "' AND REQUESTSTATUS != '" + cancelled + "'  );";

	tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
	paramInit(tw.local.parentODCRequest.parentRequestNo);

	if (tw.local.parentODCRequest.requestType.value != reversal) {
		//check outstanding amount >0
		j++;
		i = 0;
		tw.local.sqlStatements[j] = {};
		tw.local.sqlStatements[j].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM " + tw.env.LKP_DB_Schema + ".ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND (REQUESTTYPE = '" + amend + "' OR REQUESTTYPE = '" + recreate + "' OR REQUESTTYPE = '" + create + "' OR REQUESTTYPE = '" + collection + "') AND (REQUESTSTATE = '" + final + "' OR REQUESTSTATE = '" + collected + "') AND REQUESTSTATUS='" + completed + "' AND OUTSTANDINGAMOUNT =0);";
		tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
		paramInit(tw.local.parentODCRequest.parentRequestNo);
	}
}


// tw.local.parentODCRequest.requestType.value == amend || tw.local.parentODCRequest.requestType.value == collection || tw.local.parentODCRequest.requestType.value == closure || tw.local.parentODCRequest.requestType.value == reversal

ns16:extensionElements.ns2:postAssignmentScript:
tw.local.isFound = true;

if (tw.local.results[0].rows.listLength == 0) {
	tw.local.message = "Request number does not exist or is in another running request ";
	tw.local.isFound = false;
}

if (!!tw.local.results[1]) {
	if (tw.local.results[1].rows.listLength > 0) {
		tw.local.message = "Request number is in another running request ";
		tw.local.isFound = false;
	}
}

tw.local.parentODCRequest.collectionDone = false;

if (!!tw.local.results[2]) {
	if (tw.local.results[2].rows[0].data[0] > 0) {
		if (tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Recreate) {
			tw.local.message = "A collection request exists. There must be no collection request to proceed.";
			tw.local.isFound = false;
		}
		tw.local.parentODCRequest.FinancialDetailsFO = new tw.object.FinancialDetailsFO();
		tw.local.parentODCRequest.FinancialDetailsFO.totalCollectedAmount = tw.local.results[2].rows[0].data[0];
		tw.local.parentODCRequest.collectionDone = true;
	}
}

if (!!tw.local.results[3]) {
	if (tw.local.results[3].rows.listLength > 0) {
		tw.local.message = "Request can not be started.Closure request is completed for this request number.";
		tw.local.isFound = false;
	}
}

if (tw.local.parentODCRequest.requestType.value != tw.epv.RequestType.Create +"") {
	if (!!tw.local.results[4]) {
		if (tw.local.results[4].rows.listLength > 0) {
			if (tw.local.results[4].rows[0].data[0] == tw.epv.RequestState.Reversed) {
				tw.local.message = "Request can not be started.Reversal request is completed for this request number.";
				tw.local.isFound = false;
			}
		}
	}

	if (tw.local.parentODCRequest.requestType.value != tw.epv.RequestType.Reversal) {
		if (!!tw.local.results[5]) {
			if (tw.local.results[5].rows.listLength > 0) {
				tw.local.message = "Request can not be started as the Outstanding Amount = 0";
				tw.local.isFound = false;
			}
		}
	}
}


// tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Collection || tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Closure || tw.local.parentODCRequest.requestType.value == tw.epv.RequestType.Reversal || tw.local.parentODCRequest.requestType.value == "" + tw.epv.RequestType.Recreate

if (tw.local.results[0].rows.listLength == 0) {

	 tw.local.message = "Request number does not exist or is in another running request";

	 tw.local.isFound = false;
	

}

ns16:scriptTask.ns16:script:
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var j = 0;
var i = 0;
function paramInit (value) {
	tw.local.sqlStatements[j].parameters[i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[j].parameters[i].value = value;
	i++;
}
//------------------------------------- Get ODC -------------------------------------------- 
var final = "" +tw.epv.RequestState.Final;
var closed = "" + tw.epv.RequestState.Closed;
var reversed = "" + tw.epv.RequestState.Reversed;
var collected = ""+ tw.epv.RequestState.Collection;
var amend = "" + tw.epv.RequestType.Amendment;
var recreate = "" + tw.epv.RequestType.Recreate;
var collection = "" + tw.epv.RequestType.Collection;
var closure = "" + tw.epv.RequestType.Closure;
var reversal = "" + tw.epv.RequestType.Reversal;
var create = "" + tw.epv.RequestType.Create;
var completed = "" + tw.epv.Status.completed; 
var approved = "" + tw.epv.Status.Approved;

tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT ID, REQUESTNO, REQUESTNATURE, REQUESTTYPE, REQUESTDATE, REQUESTSTATE, REQUESTSTATUS, PARENTREQUESTNO, FCCONTRACTNO, CONTRACTSTAGE, EXPORTPURPOSE, PAYMENTTERMS, PRODUCTCATEGORY, COMMODITYDESCRIPTION, CIF, CUSTOMERNAME, BASEDATE, VALUEDATE, TENORDAYS, TRANSITDAYS, CONTRACTMATURITYDATE, USERREF, PRODUCTCODE, PRODUCTDESC, STAGE, SOURCEREF, TRADEFOREFNO, DISCOUNT, EXTRACHARGES, OURCHARGES, AMOUNTSIGHT, AMOUNTDEFNOAVALIZATION, AMOUNTDEFAVALIZATION, COLLECTABLEAMOUNT, OUTSTANDINGAMOUNT, MATURITYDATE, MATURITYDAYS, FINANCEAPPROVALNO, HUBCODE, HUBNAME, LIQAMOUNT, LIQCURRENCY, COLLECTIONCURRENCY, STANDARDEXRATE, NEGOTIATEDEXRATE, ALLOCATEDAMOUNT, TOTALALLOCATEDAMOUNT, TRANSACTIONREFNO, CBECLASSIFICATION, SHIPMENTMETHOD, SHIPMENTDATE, REVERSALREASON, CLOSUREREASON, IMPORTERNAME, IMPORTERCOUNTRY, IMPORTERADDRESS, IMPORTERPHONENO, IMPORTERBANK, BICCODE, IBANACCOUNT, BANKCOUNTRY, BANKADDRESS, BANKPHONENO, COLLECTINGBANKREF, CURRENTSTEPNAME, SUBSTATUS, BPMINSTANCENUMBER, REQUESTCURRENCY, MAXIMUMCOLLECTIONDATE, DOCUMENTAMOUNT, ADVANCEAMOUNT, CHARGESACCOUNT, COLLECTIONACCOUNT, ISLIQUIDATED, LIQDEBITVALUEDATE, LIQCREDITVALUEDATE, LIQDEBITACCNUM, LIQCREDITACCOUNTCLASS, LIQCREDITBRANCHCODE, LIQCREDITBALANCESIGN, LIQCREDITACCOUNTCURRENCY, LIQCREDITACCOUNTBALANCE, LIQCREDITAMOUNTINACCOUNT, COUNTRYOFORIGIN, BRANCHNAME, INITIATOR, FCCONTRACTNO2, FCCONTRACTNO3, CHARGESACCOUNTCURRENCY, CHARGESACCOUNTBALANCE, COLLECTIONACCOUNTCURRENCY, COLLECTIONACCOUNTBALANCE, CUSTOMERNAMEINDOC, CUSTOMERADDRESSINDOC, FOLDERPATH, CBEGOODSCODE, GOVERNMENTCOTTON, INCOTERMS, OPERATIONTYPECODE, GOODDESTINATION, REBATEAMOUNT FROM "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND (REQUESTTYPE = '"+amend+"' OR REQUESTTYPE = '"+recreate+"' OR REQUESTTYPE = '"+create+"') AND REQUESTSTATE = '"+final+"'  AND REQUESTSTATUS='"+completed+"');";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);   

j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
//get lastest outstanding amount
tw.local.sqlStatements[j].sql="SELECT OUTSTANDINGAMOUNT FROM "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND (REQUESTSTATE = '"+final+"' OR REQUESTSTATE = '"+collected+"' )AND REQUESTSTATUS='"+completed+"')";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
//get initiator of create request
tw.local.sqlStatements[j].sql="SELECT INITIATOR FROM "+ tw.env.LKP_DB_Schema +".ODC_REQUESTINFO WHERE PARENTREQUESTNO = ? AND REQUESTSTATE = '"+final+"' AND REQUESTSTATUS='"+completed+"'";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.parentODCRequest.parentRequestNo);

//j++;
//i=0;
//tw.local.sqlStatements[j] = new tw.object.SQLStatement();
//tw.local.sqlStatements[j].sql="SELECT OUTSTANDINGAMOUNT FROM "+ tw.env.DBSchema +".ODC_REQUESTINFO WHERE ID = (SELECT max(ID) FROM "+ tw.env.DBSchema +".ODC_REQUESTINFO WHERE  PARENTREQUESTNO = ? AND ( REQUESTTYPE = '"+recreate+"' OR REQUESTTYPE = '"+create+"'  OR REQUESTTYPE = '"+amend+"') AND REQUESTSTATE = '"+final+"'  AND REQUESTSTATUS='"+completed+"')";
//tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
//paramInit(tw.local.parentODCRequest.parentRequestNo);

tw.local.errorMSG = "This CIF Number Not related to Parent Request Number";
tw.local.isCIFMatch = false;


tw.local.parentODCRequest.CustomerInfo = tw.local.customerInfo;
tw.local.parentODCRequest.cif = tw.local.parentODCRequest.CustomerInfo.cif;
tw.local.parentODCRequest.customerName =tw.local.parentODCRequest.CustomerInfo.customerName;

tw.local.parentODCRequest.requestNature.value = tw.local.requestNature;
tw.local.parentODCRequest.requestType.value = tw.local.requestType;

tw.local.parentODCRequest.ImporterName = null;
tw.local.parentODCRequest.requestDate = null;

if ( tw.local.requestType == tw.epv.RequestType.Recreate ){
	var documentAmount = tw.local.parentODCRequest.FinancialDetailsBR.documentAmount || 0;
	var extraCharges =  tw.local.parentODCRequest.FinancialDetailsFO.extraCharges || 0;
	var discount = tw.local.parentODCRequest.FinancialDetailsFO.discount || 0;
	var amountAdvanced = tw.local.parentODCRequest.FinancialDetailsBR.amountAdvanced || 0;
	var calcAmnt = documentAmount + extraCharges - discount - amountAdvanced;
	tw.local.parentODCRequest.FinancialDetailsFO.collectableAmount = calcAmnt;
}

var i = 0 - 1;
var j = 0 - 1;
function getnext() {
	i++;
	var results = null;
	if (!!tw.local.results[0]) {
		if (!!tw.local.results[0].rows[0]) results = tw.local.results[0].rows[0].data[i];
	} else results = null;
	return results;
}

var amend = "" + tw.epv.RequestType.Amendment;
var recreate = "" + tw.epv.RequestType.Recreate;
var collection = "" + tw.epv.RequestType.Collection;
var closure = "" + tw.epv.RequestType.Closure;
var reversal = "" + tw.epv.RequestType.Reversal;

tw.local.parentODCRequest.lastRequestID = getnext();
//tw.local.parentODCRequest = new tw.object.ODCRequest();
tw.local.parentODCRequest.requestNo = getnext();
tw.local.parentODCRequest.latestRequestNo = tw.local.parentODCRequest.requestNo;
