tw.local.parentODCRequest.requestType.name = tw.local.requestType;
tw.local.parentODCRequest.requestType.value = tw.local.requestType;
tw.local.parentODCRequest.requestDate = getnext();
tw.local.parentODCRequest.BasicDetails.requestState = getnext();
//tw.local.parentODCRequest.appInfo = new tw.object.AppInfo();
//tw.local.parentODCRequest.appInfo.status = getnext ();
getnext();
tw.local.parentODCRequest.parentRequestNo = getnext();
tw.local.parentODCRequest.BasicDetails.flexCubeContractNo = getnext();
tw.local.parentODCRequest.BasicDetails.contractStage = getnext();
tw.local.parentODCRequest.BasicDetails.exportPurpose = new tw.object.NameValuePair();
tw.local.parentODCRequest.BasicDetails.exportPurpose.name = getnext();
tw.local.parentODCRequest.BasicDetails.paymentTerms = new tw.object.NameValuePair();
tw.local.parentODCRequest.BasicDetails.paymentTerms.name = getnext();
