tw.local.parentODCRequest.BasicDetails.productCategory.name = getnext();
tw.local.parentODCRequest.BasicDetails.commodityDescription = getnext();

var isLiquidated = getnext();
//       if(isLiquidated == "0")
//        tw.local.parentODCRequest.isLiquidated = false;
//        else
//        tw.local.parentODCRequest.isLiquidated = true;

i--;
tw.local.parentODCRequest.CustomerInfo = new tw.object.CustomerInfo();
tw.local.parentODCRequest.CustomerInfo.cif = getnext();
tw.local.parentODCRequest.CustomerInfo.customerName = getnext();
