tw.local.parentODCRequest.ContractCreation.baseDate = getnext();
tw.local.parentODCRequest.ContractCreation.valueDate = getnext();
tw.local.parentODCRequest.ContractCreation.tenorDays = getnext();
tw.local.parentODCRequest.ContractCreation.transitDays = getnext();
tw.local.parentODCRequest.ContractCreation.maturityDate = getnext();
tw.local.parentODCRequest.ContractCreation.userReference = getnext();
tw.local.parentODCRequest.ContractCreation.productCode = new tw.object.NameValuePair();
tw.local.parentODCRequest.ContractCreation.productCode.value = getnext();
tw.local.parentODCRequest.ContractCreation.productDescription = getnext();
tw.local.parentODCRequest.ContractCreation.productCode.name = tw.local.parentODCRequest.ContractCreation.productDescription;
tw.local.parentODCRequest.ContractCreation.Stage = getnext();
tw.local.parentODCRequest.ContractCreation.sourceReference = getnext();
tw.local.parentODCRequest.FinancialDetailsFO.referenceNo = getnext();
tw.local.parentODCRequest.FinancialDetailsFO.discount = getnext();
tw.local.parentODCRequest.FinancialDetailsFO.extraCharges = getnext();
tw.local.parentODCRequest.FinancialDetailsFO.ourCharges = getnext();
tw.local.parentODCRequest.FinancialDetailsFO.amountSight = getnext();
tw.local.parentODCRequest.FinancialDetailsFO.amountDefNoAvalization = getnext();
tw.local.parentODCRequest.FinancialDetailsFO.amountDefAvalization = getnext();
tw.local.parentODCRequest.FinancialDetailsFO.collectableAmount = getnext();
tw.local.parentODCRequest.oldCollectableAmount = tw.local.parentODCRequest.FinancialDetailsFO.collectableAmount;

if (!!tw.local.results[1]) {
	if (!!tw.local.results[1].rows[0]) tw.local.parentODCRequest.FinancialDetailsFO.outstandingAmount = tw.local.results[1].rows[0].data[0];
}
getnext();
